entries[29465] = { ["name"] = "Schwarzer Schlachtenschreiter", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Schlachtenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein ordentlich beschleunigter Gnom in der Schlacht ist etwas schrecklich Schönes. - Hochtüftler Mekkadrill\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15" }
entries[29466] = { ["name"] = "Schwarzer Kriegskodo", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegskodo oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Stallmeister der Kor'kron züchten die schwarzen Kriegskodos wegen ihres aggressiven und unberechenbaren Verhaltens. Ihr Trompeten zeigt an, dass bald Blut fließen wird.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15" }
entries[29467] = { ["name"] = "Schwarzer Kriegswidder", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegswidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Zwerge lieben ihre Widdergefährten, weil diese sich furchtlos ins Gefecht stürzen.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15" }
entries[29468] = { ["name"] = "Zaumzeug des schwarzen Schlachtrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schwarzes Schlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dazu ausgebildet, den heftigsten Nahkampf auf den grausamsten Schlachtfeldern auszuhalten.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15" }
entries[29469] = { ["name"] = "Horn des schwarzen Kriegswolfs", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegswolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Werden von den Wachen von Orgrimmar wegen ihres gut ausgeprägten Geruchssinns geschätzt.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15" }
entries[29470] = { ["name"] = "Rotes Skelettschlachtross", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares rotes Skelettschlachtross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn gefallene Helden in den Untod erweckt werden, folgen ihnen auch ihre Pferde.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15" }
entries[29471] = { ["name"] = "Zügel des schwarzen Kriegstigers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegstiger oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wie die entfernt verwandten Nachtsäbler sind Tiger für ihre messerscharfen Klauen, ihre unglaubliche Beweglichkeit und ihre Liebe dafür, hinter den Ohren gekrault zu werden, bekannt.\"\nVerkäufer:\nLeutnant Karter\nZone:\nSturmwind\nKosten:\n15" }
entries[29472] = { ["name"] = "Pfeife des schwarzen Kriegsraptors", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegsraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Aus derselben brutalen Familie der Raptoren gezüchtet, die auch Ohgan gezeugt und dem Imperium der Gurubashi den Sieg gebracht hat.\"\nVerkäufer:\nRäuber Bork\nZone:\nOrgrimmar\nKosten:\n15" }
