entries[29713] = { ["name"] = "Muster: Trommeln der Panik", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Panik.\nBenötigt Lederverarbeitung der Scherbenwelt (70)\nBenötigt Hüter der Zeit\n- Wohlwollend\nVerkaufspreis:\nTrommeln der Panik\nBenutzen: Unheimliche Klänge lassen 5 Feinde in einem Umkreis von 8 Metern 2 Sek. lang voller Schrecken flüchten. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Dämonenhautleder (4)" }
entries[29714] = { ["name"] = "Muster: Trommeln der Wiederherstellung", ["text"] = "Benutzen: Lehrt Euch die Herstellung von Trommeln der Wiederherstellung.\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nTrommeln der Wiederherstellung\nBenutzen: Stellt 15 Sek. lang insgesamt 170 Gesundheit und Mana bei allen Gruppenmitgliedern in der Nähe wieder her. Unwirksam bei Zielen über Stufe 50. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppen (4)" }
entries[29717] = { ["name"] = "Muster: Trommeln der Schlacht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Schlacht.\nBenötigt Lederverarbeitung der Scherbenwelt (65)\nBenötigt Die Sha'tar\n- Wohlwollend\nVerkaufspreis:\nTrommeln der Schlacht\nBenutzen: Erhöht das Tempo aller Gruppenmitglieder in der Nähe um bis zu 15 . Hält 30 Sek. lang an. Unwirksam bei Zielen über Stufe 50. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (50)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Dickes Grollhufleder (4)" }
entries[29718] = { ["name"] = "Muster: Trommeln des Tempos", ["text"] = "Benutzen: Lehrt Euch die Herstellung von Trommeln des Tempos.\nBenötigt Lederverarbeitung der Scherbenwelt (45)\nVerkaufspreis:\nTrommeln des Tempos\nBenutzen: Erhöht die Bewegungsgeschwindigkeit aller in der Nähe befindlichen Gruppenmitglieder um 15%. Hält 30 Sek. lang an. Kann nicht über Stufe 35 verwendet werden. (2 Min Abklingzeit)\n50 Aufladungen\nBenötigt Lederverarbeitung der Scherbenwelt (40)\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Windschuppen (4)" }
entries[29719] = { ["name"] = "Muster: Kobrahautbeinrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Kobrahautbeinrüstung.\nBenötigt Lederverarbeitung der Scherbenwelt (35)\nBenötigt Ehrenfeste\n- Wohlwollend\nVerkaufspreis:\nKobrahautbeinrüstung\nBenutzen: Bringt dauerhaft eine Kobrahautrüstung an einer Hose an, die die Angriffskraft um 2 und den kritischen Trefferwert um 3 erhöht. Durch diese Verzauberung wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (4), Kobraschuppen (2), Urluft (4)" }
