entries[29738] = { ["name"] = "Phiole mit Leerenschreckensschlamm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Voll mit blubberndem Schlamm.\"" }
entries[29739] = { ["name"] = "Arkaner Foliant", ["text"] = "\"Die Seher in der Bibliothek der Seher wären sicherlich an diesem Gegenstand interessiert.\"" }
entries[29740] = { ["name"] = "Teuflische Waffen", ["text"] = "\"Nur die Aldor im Schrein des Endlosen Lichts sind in der Lage diesen Gegenstand von der dämonischen Besudelung zu befreien.\"" }
