entries[30311] = { ["name"] = "Warpschnitter", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Einhändig Schwert\n4 - 7 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nHaltbarkeit 130 / 130\nTrefferchance: Erhöht 30 Sek. lang die Bewegungsgeschwindigkeit um 50% und das Nahkampfangriffstempo um 20%.\nVerkaufspreis:" }
entries[30312] = { ["name"] = "Klinge der Unendlichkeit", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Einhändig Dolch\n3 - 5 Schaden Geschwindigkeit 1.80\n(2.2 Schaden pro Sekunde)\n+2 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nHaltbarkeit 95 / 95\nAnlegen: Erhöht den vom Ziel erlittenen Zauberschaden um 5% und bannt bei einem Treffer mit einer Nahkampffähigkeit Kael'thas' Fähigkeit 'Gedankenkontrolle'. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an.\nVerkaufspreis:" }
entries[30313] = { ["name"] = "Stab der Auflösung", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Zweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nHaltbarkeit 145 / 145\nBenutzen: Umgibt verbündete Ziele in einem Umkreis von 30 Metern mit einem mentalen Schutzfeld, wodurch die Betroffenen immun gegen Betäubungs-, Schweige- und Desorientierungseffekte werden. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[30314] = { ["name"] = "Phasenverschobenes Bollwerk", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Schildhand Schild\n45 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\n+ 3 Ausweichen\nHaltbarkeit 145 / 145\nBenutzen: Hüllt den Zaubernden in ein Schild, absorbiert 1 Schaden und macht ihn 4 Sek. lang immun gegenüber Furcht- und Verlangsamungseffekten. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
