entries[30317] = { ["name"] = "Kosmische Macht", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Einhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+12 Intelligenz\n+3 Ausdauer\n+ 9 Vielseitigkeit\nHaltbarkeit 130 / 130\nAnlegen: Befreundete Ziele der Heilung des Zaubernden erhalten einen Effekt, der 30 Sek. lang erlittenen Feuer- und Schattenschaden um 50% verringert.\nVerkaufspreis:" }
entries[30318] = { ["name"] = "Netherbespannter Langbogen", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Distanz Bogen\n7 - 10 Schaden Geschwindigkeit 3.00\n(2.8 Schaden pro Sekunde)\n+4 Ausdauer\n+ 14 kritische Distanztrefferwertung\n+ 6 Distanzangriffskraft\nHaltbarkeit 145 / 145\nKlassen: Jäger\nAnlegen: Erhöht Euren Schadensbonus für kritische Treffer durch Distanzwaffen um 50%.\nTrefferchance: Erhöht den erlittenen körperlichen Schaden des Ziels 30 Sek. lang um 5%. Dieser Effekt ist stapelbar.\nVerkaufspreis:" }
